import type { AppIcon } from "apps";

// Generated by scripts/icon.ts from the vendor's logo.
export const icons: readonly AppIcon[] = [
  {
    "src": "data:image/svg+xml;base64,",
    "mimeType": "image/svg+xml"
  }
];

import {
  accountRouter,
  decodeJson,
  defineApp,
  defineProvider,
  oauth2,
  object,
  router,
  secrets,
  string,
  withApprovals,
} from "apps";
import { always, never } from "apps/operations/approval";
import { liveOpenapiRouter } from "apps/openapi";
import { icons } from "./icon.js";
import { options } from "./openapi.js";

const TokenContext = object({ user: object({ id: string(), name: string() }) });

const miro = defineProvider({
  name: "Miro",
  hosts: ["api.miro.com"],
  auth: {
    token: secrets({
      label: "Access token",
      fields: object({ token: string({ minLength: 1 }) }),
    }),
    // Use the host-managed client, or enter your own client under Advanced.
    oauth: oauth2({
      authorizationUrl: "https://miro.com/oauth/authorize",
      tokenUrl: "https://api.miro.com/v1/oauth/token",
      tokenEndpointAuthMethod: "client_secret_post",
      scopes: ["boards:read", "boards:write"],
    }),
  },
  async health({ account, fetch, signal }) {
    const token = account.method === "oauth" ? account.fields.access_token : account.fields.token;
    const response = await fetch("https://api.miro.com/v1/oauth-token", {
      signal,
      headers: { Authorization: `Bearer ${token}`, Accept: "application/json" },
    });
    const context = await decodeJson(response, TokenContext);
    return {
      accountInfo: { externalId: context.user.id, username: context.user.name },
    };
  },
});

export default defineApp(
  { user: { accounts: { miro: miro.many() } }, icons },
  async ({ user, cache, fetch, signal }) => ({
    tools: router(
      await accountRouter(
        user?.accounts.miro ?? [],
        (account) =>
          withApprovals(liveOpenapiRouter({ ...options, cache, fetch, signal, account }), (tool) =>
            tool.kind === "mutation" ? always() : never(),
          ),
        { signal },
      ),
      {
        title: "Miro",
        description:
          "Miro boards, items, connectors, tags and board members through the Miro REST API.",
        icons,
      },
    ),
  }),
);

{
  "name": "@executor.sh/miro",
  "description": "Miro board content and membership, with board read/write scopes available on all plans.",
  "private": true,
  "type": "module",
  "executor": {
    "title": "Miro"
  },
  "dependencies": {
    "apps": "0.0.1-beta.104-basalt.1"
  }
}
